cases = [(0, 0), (9, 0), (10, 1), (19999, 1999), (23999, 2399), (24000, 2400), (24010, 2400), (10**30 + 9, 2400)]
checks = 0
for release in (None, \"1.0\"):
    for service_on in (\"2020-01-01\", \"2099-12-31\"):
        for charge, credit in cases:
            request = {\"command\": \"quote\", \"line\": {\"line_id\": \"L-😀\", \"account_id\": \"A\", \"subscription_id\": \"S\", \"service_on\": service_on, \"charge_cents\": charge}}
            if release is not None:
                request[\"release\"] = release
            result = subprocess.run([sys.executable, \"main.py\"], input=json.dumps(request), capture_output=True, text=True, check=True)
            assert json.loads(result.stdout) == {\"release\": \"1.0\", \"line_id\": \"L-😀\", \"credit_cents\": credit, \"amount_due_cents\": charge - credit}, result.stdout
            assert not result.stderr, result.stderr
            checks += 1
print(f\"PASS {checks} CLI checks for rounding, caps, date boundaries, and release selection\")'"
